description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa quy cách bố trí các loại vạch dọc đường (vạch 1.1, 1.4, vạch tim đường) trong phạm vi đường cong nằm không đảm bảo tầm nhìn vượt xe an toàn.",
  "items": [
    {
      "identifier": "Vạch 1.1",
      "visual_or_geometric_features": "Vạch đơn, đứt nét, màu vàng. Hình vẽ minh họa đoạn nét liền và đoạn nét đứt xen kẽ trên đường cong.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều. Xe được phép cắt qua để sử dụng làn ngược chiều từ cả hai phía. Trong phạm vi đường cong nằm bán kính nhỏ, chọn chiều dài đoạn nét liền và đoạn nét đứt nhỏ để tăng tính dẫn hướng."
    },
    {
      "identifier": "Vạch 1.4",
      "visual_or_geometric_features": "Vạch đôi song song, gồm một vạch nét liền và một vạch nét đứt, màu vàng.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều. Xe trên làn tiếp giáp vạch đứt được phép cắt qua; xe trên làn tiếp giáp vạch liền không được lấn làn. Trong phạm vi đường cong nằm, vạch liền được vẽ về phía có yêu cầu cấm vượt."
    },
    {
      "identifier": "Vùng cấm vượt",
      "visual_or_geometric_features": "Khu vực được khoanh tròn hoặc đánh dấu trên mặt đường cong nơi bố trí vạch liền hoặc vạch 1.4.",
      "meaning_or_specification": "Là vùng có chiều dài tầm nhìn thực tế nhỏ hơn chiều dài tầm nhìn vượt xe an toàn tối thiểu, nơi xe không được phép vượt."
    },
    {
      "identifier": "Vùng cho phép vượt",
      "visual_or_geometric_features": "Khu vực trên mặt đường cong nơi bố trí vạch 1.1 (vạch đứt nét).",
      "meaning_or_specification": "Là vùng không có yêu cầu cấm vượt ở cả hai phía, xe được phép thực hiện việc vượt xe."
    }
  ]
}
